import { test } from 'node:test';
import assert from 'node:assert/strict';
import { todosPares, algumImpar } from './solution.mjs';

test('todos pares devolve true', () => {
  assert.equal(todosPares([2, 4, 6]), true);
});

test('um ímpar basta para o some; o every exige todos', () => {
  assert.equal(todosPares([2, 3, 4]), false);
  assert.equal(algumImpar([2, 3, 4]), true);
});

test('lista vazia: every devolve true e some devolve false', () => {
  assert.equal(todosPares([]), true);
  assert.equal(algumImpar([]), false);
});

test('recusa valor que não é lista', () => {
  assert.throws(() => todosPares('24'));
});

solutionCode:
export function todosPares(lista) {
  if (!Array.isArray(lista)) {
    throw new Error('lista precisa ser um array');
  }
  return lista.every((n) => n % 2 === 0);
}

export function algumImpar(lista) {
  if (!Array.isArray(lista)) {
    throw new Error('lista precisa ser um array');
  }
  return lista.some((n) => n % 2 !== 0);
}
